#include "stdafx.h"#include "HcdElementBase.h"struct STOT_P{#include "PrivateVars/TOT.h"};class KTOT : public KHcdElementBase  , protected STOT_P{  tAnalog32 timeLimit;public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void OnFilledProjectSettings();  virtual void StepCalc( SStepCalcParams &params );};static KHcdFactory _TOT("TOT", KTOT::Create);IHcdElement *KTOT::Create(){  return new KTOT;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KTOT, 11 )void KTOT::InitParm(){#include "PrivateVars/TOT.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KTOT::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;}void KTOT::OnFilledProjectSettings(){  ASSD( !strcmp(InputRate,"Per Hour") );  timeLimit = 60.f * 60.f;}void KTOT::StepCalc( SStepCalcParams &params ){  tAnalog32 L = UseRemotePreset ? RPRE : LocalPreset;;  if( RST )  {    if( 0==PresetTrigger.V )      OUTD0 = 0;    else      OUTD0 = L;  }  if( !EN )    return;  td += params.dtS;  if( td < timeLimit )  {    PREI = 0;    return;  }  if( 0==PresetTrigger.V )//Increasing  {    OUTD0 += INU0;    if( OUTD0 > L )    {      PREI = 1;      OUTD0 = 0;    }  }  else  {    OUTD0 -= INU0;    if( OUTD0 < 0 )    {      PREI = 1;      OUTD0 = L;    }  }  td = 0;}